{"content":"/**
 * Fixed-width plain-text tables: display width, wrapping, padding and layout.
 */

/** Error raised for invalid table input. */
export class TableError extends Error {
  /**
   * @param {string} code Stable machine-readable reason.
   * @param {string} message Human-readable detail.
   */
  constructor(code, message) {
    super(message);
    this.name = 'TableError';
    this.code = code;
  }
}

/**
 * Display width of a string in terminal columns.
 *
 * @param {string} text Text to measure.
 * @returns {number} Column count.
 */
export function stringWidth(text) {
  if (typeof text !== 'string') {
    throw new TableError('BAD_CELL', 'cell must be a string');
  }

  let width = 0;

  for (const char of text) {
    const code = char.codePointAt(0);

    // Characters that count as 0 columns
    if (
      code < 0x0020 || 
      code === 0x007F ||
      code === 0x200B ||
      code === 0x200C ||
      code === 0x200D ||
      code === 0xFEFF ||
      (code >= 0x0300 && code <= 0x036F)
    ) {
      // width += 0; // explicitly zero
    } 
    // Characters that count as 2 columns
    else if (
      (code >= 0x1100 && code <= 0x115F) ||
      (code >= 0x2E80 && code <= 0x303E) ||
      (code >= 0x3041 && code <= 0x33FF) ||
      (code >= 0x3400 && code <= 0x4DBF) ||
      (code >= 0x4E00 && code <= 0x9FFF) ||
      (code >= 0xA000 && code <= 0xA4CF) ||
      (code >= 0xAC00 && code <= 0xD7A3) ||
      (code >= 0xF900 && code <= 0xFAFF) ||
      (code >= 0xFE10 && code <= 0xFE19) ||
      (code >= 0xFE30 && code <= 0xFE6F) ||
      (code >= 0xFF00 && code <= 0xFF60) ||
      (code >= 0xFFE0 && code <= 0xFFE6) ||
      (code >= 0x1F300 && code <= 0x1F64F) ||
      (code >= 0x1F900 && code <= 0x1F9FF) ||
      (code >= 0x20000 && code <= 0x2FFFD) ||
      (code >= 0x30000 && code <= 0x3FFFD)
    ) {
      width += 2;
    } 
    // Everything else counts as 1
    else {
      width += 1;
    }
  }

  return width;
}

/**
 * Wrap cell text to a column width.
 *
 * @param {string} text Cell text; explicit newlines start a new line.
 * @param {number} width Column width in display columns.
 * @returns {string[]} Wrapped lines, at least one.
 */
export function wrapCell(text, width) {
  if (typeof text !== 'string') {
    throw new TableError('BAD_CELL', 'cell must be a string');
  }

  if (!Number.isInteger(width) || width < 1) {
    throw new TableError('BAD_WIDTH', 'width must be a positive integer');
  }

  // Split by newlines and process each piece
  const pieces = text.split('\n');
  const result = [];

  for (const piece of pieces) {
    // Process each piece separately
    const lines = wrapPiece(piece, width);
    result.push(...lines);
  }

  // Ensure at least one line
  if (result.length === 0) {
    result.push('');
  }

  return result;
}

/**
 * Helper function to wrap a single piece (no newlines)
 * @param {string} piece 
 * @param {number} width 
 * @returns {string[]}
 */
function wrapPiece(piece, width) {
  // Handle empty or whitespace-only pieces
  if (piece.trim() === '') {
    return [''];
  }

  // Split into words (sequences of non-space characters)
  const words = piece.trim().split(/\s+/);

  if (words.length === 0) {
    return [''];
  }

  // Process each word
  const chunks = [];

  for (const word of words) {
    const wordWidth = stringWidth(word);

    // Check if single character is too wide
    if (word.length === 1 && wordWidth > width) {
      throw new TableError('UNWRAPPABLE', 'character is wider than the column');
    }

    // If word fits entirely, add it as-is
    if (wordWidth <= width) {
      chunks.push(word);
    } else {
      // Word needs to be broken into chunks
      let remaining = word;
      while (stringWidth(remaining) > width) {
        // Find the largest prefix that fits
        let splitPos = 1;
        while (splitPos < remaining.length) {
          const prefix = remaining.substring(0, splitPos + 1);
          if (stringWidth(prefix) > width) {
            break;
          }
          splitPos++;
        }

        // If we couldn't fit even one character, the character is too wide
        if (splitPos === 0) {
          throw new TableError('UNWRAPPABLE', 'character is wider than the column');
        }

        const chunk = remaining.substring(0, splitPos);
        chunks.push(chunk);
        remaining = remaining.substring(splitPos);
      }

      // Add the remaining part
      if (remaining.length > 0) {
        chunks.push(remaining);
      }
    }
  }

  // Now pack chunks into lines greedily
  const lines = [];
  let currentLine = [];
  let currentWidth = 0;

  for (const chunk of chunks) {
    const chunkWidth = stringWidth(chunk);
    const spaceNeeded = currentLine.length > 0 ? 1 : 0; // space between words

    if (currentWidth + spaceNeeded + chunkWidth <= width) {
      // Add to current line
      if (currentLine.length > 0) {
        currentLine.push(' ');
        currentWidth += 1;
      }
      currentLine.push(chunk);
      currentWidth += chunkWidth;
    } else {
      // Start new line
      lines.push(currentLine.join(''));
      currentLine = [chunk];
      currentWidth = chunkWidth;
    }
  }

  // Add the last line
  if (currentLine.length > 0) {
    lines.push(currentLine.join(''));
  }

  return lines;
}

/**
 * Pad a single line to an exact display width.
 *
 * @param {string} text Line that already fits.
 * @param {number} width Target column width.
 * @param {'left'|'right'|'center'} [align] Alignment, left by default.
 * @returns {string} Padded line.
 */
export function padCell(text, width, align = 'left') {
  if (typeof text !== 'string') {
    throw new TableError('BAD_CELL', 'cell must be a string');
  }

  if (!Number.isInteger(width) || width < 1) {
    throw new TableError('BAD_WIDTH', 'width must be a positive integer');
  }

  if (align !== 'left' && align !== 'right' && align !== 'center') {
    throw new TableError('BAD_ALIGN', `unknown alignment: ${align}`);
  }

  const textWidth = stringWidth(text);

  if (textWidth > width) {
    throw new TableError('CELL_TOO_WIDE', 'content is wider than the column');
  }

  const paddingNeeded = width - textWidth;

  if (align === 'left') {
    return text + ' '.repeat(paddingNeeded);
  } else if (align === 'right') {
    return ' '.repeat(paddingNeeded) + text;
  } else { // center
    const leftPadding = Math.floor(paddingNeeded / 2);
    const rightPadding = paddingNeeded - leftPadding;
    return ' '.repeat(leftPadding) + text + ' '.repeat(rightPadding);
  }
}

/**
 * Render rows as a fixed-width table.
 *
 * @param {string[][]} rows Rows of cells.
 * @param {{widths: number[], align?: string[], header?: boolean}} options Layout options.
 * @returns {string} Table text without a trailing newline.
 */
export function formatTable(rows, options) {
  // Validate options
  if (options === null || typeof options !== 'object') {
    throw new TableError('BAD_OPTIONS', 'options must be an object');
  }

  // Validate widths
  if (!Array.isArray(options.widths) || options.widths.length === 0) {
    throw new TableError('BAD_WIDTH', 'widths must be a non-empty array of positive integers');
  }

  for (const width of options.widths) {
    if (!Number.isInteger(width) || width < 1) {
      throw new TableError('BAD_WIDTH', 'widths must be a non-empty array of positive integers');
    }
  }

  const numCols = options.widths.length;

  // Validate align if provided
  if (options.align !== undefined) {
    if (!Array.isArray(options.align)) {
      throw new TableError('BAD_ALIGN', `align must have ${numCols} entries`);
    }

    if (options.align.length !== numCols) {
      throw new TableError('BAD_ALIGN', `align must have ${numCols} entries`);
    }

    for (const align of options.align) {
      if (align !== 'left' && align !== 'right' && align !== 'center') {
        throw new TableError('BAD_ALIGN', `unknown alignment: ${align}`);
      }
    }
  }

  // Validate rows
  if (!Array.isArray(rows)) {
    throw new TableError('BAD_ROWS', 'rows must be an array');
  }

  // Validate each row
  for (let rowIdx = 0; rowIdx < rows.length; rowIdx++) {
    const row = rows[rowIdx];

    if (!Array.isArray(row)) {
      throw new TableError('BAD_ROW_LENGTH', `row ${rowIdx} has 0 cells, expected ${numCols}`);
    }

    if (row.length !== numCols) {
      throw new TableError('BAD_ROW_LENGTH', `row ${rowIdx} has ${row.length} cells, expected ${numCols}`);
    }

    for (let colIdx = 0; colIdx < row.length; colIdx++) {
      const cell = row[colIdx];
      if (typeof cell !== 'string') {
        throw new TableError('BAD_CELL', `cell at row ${rowIdx}, column ${colIdx} is not a string`);
      }
    }
  }

  // Handle empty rows case
  if (rows.length === 0) {
    return '';
  }

  // Process each cell: wrap to column width
  const wrappedRows = [];
  let maxLines = 0;

  for (const row of rows) {
    const wrappedRow = [];
    for (let colIdx = 0; colIdx < row.length; colIdx++) {
      const cell = row[colIdx];
      const width = options.widths[colIdx];
      const wrappedCell = wrapCell(cell, width);
      wrappedRow.push(wrappedCell);
      maxLines = Math.max(maxLines, wrappedCell.length);
    }
    wrappedRows.push(wrappedRow);
  }

  // Pad each cell to have exactly maxLines lines
  const paddedRows = [];
  for (const wrappedRow of wrappedRows) {
    const paddedRow = [];
    for (let colIdx = 0; colIdx < wrappedRow.length; colIdx++) {
      const wrappedCell = wrappedRow[colIdx];
      const width = options.widths[colIdx];
      const align = options.align && options.align[colIdx] ? options.align[colIdx] : 'left';

      // Pad the cell to maxLines lines
      const paddedCell = [];
      for (let lineIdx = 0; lineIdx < maxLines; lineIdx++) {
        const line = lineIdx < wrappedCell.length ? wrappedCell[lineIdx] : '';
        const paddedLine = padCell(line, width, align);
        paddedCell.push(paddedLine);
      }
      paddedRow.push(paddedCell);
    }
    paddedRows.push(paddedRow);
  }

  // Build the table lines
  const tableLines = [];
  for (let lineIdx = 0; lineIdx < maxLines; lineIdx++) {
    const lineCells = [];
    for (let colIdx = 0; colIdx < numCols; colIdx++) {
      lineCells.push(paddedRows[colIdx][lineIdx]);
    }
    tableLines.push(lineCells.join(' | '));
  }

  // Add header rule if needed
  if (options.header === true) {
    const headerCells = [];
    for (let colIdx = 0; colIdx < numCols; colIdx++) {
      const width = options.widths[colIdx];
      headerCells.push('-'.repeat(width));
    }
    const headerRule = headerCells.join('-+-');
    tableLines.splice(1, 0, headerRule);
  }

  return tableLines.join('\n');
}","file_path":"src/index.js"}

