// Build the table lines
const tableLines = [];
for (let lineIdx = 0; lineIdx < maxLines; lineIdx++) {
  const lineCells = [];
  for (let rowIdx = 0; rowIdx < paddedRows.length; rowIdx++) {
    // For each row, collect one cell from each column at lineIdx
    for (let colIdx = 0; colIdx < numCols; colIdx++) {
      lineCells.push(paddedRows[rowIdx][colIdx][lineIdx]);
    }
  }
  tableLines.push(lineCells.join(' | '));
}

