diffs.newText:

// Build the table lines
const tableLines = [];
for (let rowIdx = 0; rowIdx < paddedRows.length; rowIdx++) {
  const lineCells = [];
  for (let lineIdx = 0; lineIdx < maxLines; lineIdx++) {
    const cellsInLine = [];
    for (let colIdx = 0; colIdx < numCols; colIdx++) {
      cellsInLine.push(paddedRows[rowIdx][colIdx][lineIdx]);
    }
    lineCells.push(cellsInLine.join(' | '));
  }
  tableLines.push(...lineCells);
}

